import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.Dhf_H6O0.js";const o="/mbit-mcpo-proxy-download/guide/images/license-overlay.png",y=JSON.parse('{"title":"Activate Your License","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/activate-license.md","filePath":"getting-started/activate-license.md"}'),s={name:"getting-started/activate-license.md"};function r(l,e,c,d,h,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="activate-your-license" tabindex="-1">Activate Your License <a class="header-anchor" href="#activate-your-license" aria-label="Permalink to &quot;Activate Your License&quot;">​</a></h1><p>MCPBehindIT requires a license key from MindBehind IT. Activation is a one-time step that takes about 10 seconds.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Your <strong>license key</strong> (provided by MindBehind IT)</li><li>An <strong>internet connection</strong> (the key is validated online)</li></ul><h2 id="step-by-step" tabindex="-1">Step by step <a class="header-anchor" href="#step-by-step" aria-label="Permalink to &quot;Step by step&quot;">​</a></h2><ol><li>Launch MCPBehindIT. The <strong>License required</strong> overlay appears automatically.</li></ol><p><img src="'+o+'" alt="License activation overlay"></p><ol start="2"><li>Paste your license key into the <strong>License key</strong> field.</li><li>Click <strong>Activate</strong>.</li><li>If the key is valid, the overlay disappears and you see the Dashboard.</li></ol><div class="warning custom-block"><p class="custom-block-title">&quot;License validation failed&quot;</p><p>This can happen when:</p><ul><li>The key was entered incorrectly — double-check for extra spaces or missing characters.</li><li>The key is already in use on another device.</li><li>There&#39;s no internet connection — the app needs to reach the MindBehind validation server.</li></ul><p>Click <strong>Check again</strong> to retry after fixing the issue.</p></div><h2 id="how-license-validation-works" tabindex="-1">How license validation works <a class="header-anchor" href="#how-license-validation-works" aria-label="Permalink to &quot;How license validation works&quot;">​</a></h2><ul><li>Your key is checked <strong>when you activate</strong> and <strong>periodically while the app is running</strong> (every 5 minutes).</li><li>If the validation server can&#39;t be reached temporarily, the app continues to work with the last known state.</li><li>If your license becomes invalid (expired, revoked, or used on a different device), the gateway stops automatically and the activation overlay reappears.</li><li>The full key is never displayed — only a short suffix is shown in Settings for reference.</li></ul><h2 id="managing-your-license-later" tabindex="-1">Managing your license later <a class="header-anchor" href="#managing-your-license-later" aria-label="Permalink to &quot;Managing your license later&quot;">​</a></h2><p>You can update or remove your license key in <strong>Settings → License key</strong>. See <a href="./../settings/license.html">License Management</a> for details.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>License activated! Let&#39;s look at <a href="./first-launch.html">your first launch</a>.</p>',15)])])}const g=t(s,[["render",r]]);export{y as __pageData,g as default};
